import React, { useState, useEffect } from 'react';
import { WidgetDataGuard } from '../components/WidgetDataGuard';
import { DndContext, closestCenter, PointerSensor, KeyboardSensor, useSensor, useSensors, type DragEndEvent } from '@dnd-kit/core';
import { SortableContext, horizontalListSortingStrategy, useSortable, arrayMove, sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import type { WidgetProps, MappingConfig } from '../types';
import { useWidgetFetch } from '../hooks/useWidgetFetch';

const SortableHeader: React.FC<{ id: string; isDraggable: boolean }> = ({ id, isDraggable }) => {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id });
  const style = isDraggable ? { transform: CSS.Transform.toString(transform), transition } : undefined;

  return (
    <th
      ref={isDraggable ? setNodeRef : undefined}
      style={style}
      {...(isDraggable ? { ...attributes, ...listeners } : {})}
      onPointerDown={isDraggable ? e => e.stopPropagation() : undefined}
      className={`px-4 py-3 font-medium border-b border-gray-200 text-xs text-gray-500 uppercase tracking-wider whitespace-nowrap ${
        isDraggable ? 'cursor-grab select-none hover:bg-blue-50/50' : ''
      } ${isDragging ? 'bg-blue-50 shadow-md z-10' : ''}`}
    >
      {id}
    </th>
  );
};

const TableStockCritico: React.FC<WidgetProps> = ({ definition, period, isEditMode }) => {
  const { data, loading, error } = useWidgetFetch<Record<string, unknown>[]>(
    definition.widget_id, period, definition.refresh_policy, definition.field_mapping?.rename
  );

  const tableConfig = definition.config_schema as (MappingConfig & { type: 'table' }) | undefined;
  const rows = Array.isArray(data) ? data : data ? [data] : [];
  const allKeys = rows.length > 0 ? Object.keys(rows[0]) : [];
  const originalColumns = (tableConfig?.type === 'table' && tableConfig.visibleColumns?.length > 0)
    ? tableConfig.visibleColumns.filter(c => allKeys.includes(c))
    : allKeys;

  const [localColumns, setLocalColumns] = useState<string[]>(originalColumns);

  // Sincronizar cuando los datos originales cambian (ej: periodo cambió)
  useEffect(() => {
    setLocalColumns(originalColumns);
  }, [JSON.stringify(originalColumns)]);

  // Solo drag en modo vista (no edit mode del grid, para no competir)
  const isDraggable = !isEditMode && localColumns.length > 1;

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { delay: 150, tolerance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over || active.id === over.id) return;
    const oldIdx = localColumns.indexOf(active.id as string);
    const newIdx = localColumns.indexOf(over.id as string);
    if (oldIdx === -1 || newIdx === -1) return;
    setLocalColumns(arrayMove(localColumns, oldIdx, newIdx));
  };

  // Sorteo local
  let sortedRows = [...rows];
  if (tableConfig?.type === 'table' && tableConfig.sortField && allKeys.includes(tableConfig.sortField)) {
    const field = tableConfig.sortField;
    const dir = tableConfig.sortDirection === 'desc' ? -1 : 1;
    sortedRows.sort((a, b) => {
      const va = a[field], vb = b[field];
      if (typeof va === 'number' && typeof vb === 'number') return (va - vb) * dir;
      return String(va ?? '').localeCompare(String(vb ?? ''), 'es-CO') * dir;
    });
  }

  const formatCell = (val: unknown): string => {
    if (val == null) return '—';
    if (typeof val === 'object') return JSON.stringify(val);
    if (typeof val === 'number') return val.toLocaleString('es-CO');
    return String(val);
  };

  return (
    <WidgetDataGuard loading={loading} error={error} data={data}>
      {rows.length === 0 ? (
        <div className="w-full h-full flex items-center justify-center text-sm text-gray-500">Sin datos</div>
      ) : (
        <div className="w-full h-full overflow-auto custom-scrollbar">
          <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
            <SortableContext items={localColumns} strategy={horizontalListSortingStrategy}>
              <table className="w-full text-left border-collapse">
                <thead className="bg-gray-50 sticky top-0 z-[5]">
                  <tr>
                    {localColumns.map(col => (
                      <SortableHeader key={col} id={col} isDraggable={isDraggable} />
                    ))}
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-100">
                  {sortedRows.map((row, i) => (
                    <tr key={i} className="hover:bg-gray-50 transition-colors">
                      {localColumns.map(col => (
                        <td key={col} className="px-4 py-3 text-sm text-gray-700">{formatCell(row[col])}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </SortableContext>
          </DndContext>
        </div>
      )}
    </WidgetDataGuard>
  );
};

export default TableStockCritico;
